param([Parameter(Mandatory=$true)][string]$ServerUrl,[Parameter(Mandatory=$true)][string]$User1Token,[Parameter(Mandatory=$true)][string]$User2Token,[Parameter(Mandatory=$true)][string]$User3Token)
$ErrorActionPreference='Stop';$ServerUrl=$ServerUrl.TrimEnd('/');$tokens=@($User1Token,$User2Token,$User3Token)
$jobs=for($i=0;$i -lt 3;$i++){Start-Job -ScriptBlock {param($url,$token)Invoke-RestMethod -Uri "$url/api/operations/sales/next-invoice" -Headers @{Authorization="Bearer $token"}} -ArgumentList $ServerUrl,$tokens[$i]}
try{$results=$jobs|Wait-Job|Receive-Job;if($results.Count -ne 3){throw "Expected 3 client results; received $($results.Count)"};$numbers=@($results|ForEach-Object {$_.value});if(($numbers|Sort-Object -Unique).Count -ne 3){throw "Reference collision detected: $($numbers -join ', ')"}
$readJobs=for($i=0;$i -lt 3;$i++){Start-Job -ScriptBlock {param($url,$token)$h=Invoke-RestMethod -Uri "$url/api/runtime/health";$s=Invoke-RestMethod -Uri "$url/api/support/settings/company.name?def=DSE%20ERP" -Headers @{Authorization="Bearer $token"};[pscustomobject]@{Ready=$h.ready;Company=$s.value}} -ArgumentList $ServerUrl,$tokens[$i]};$reads=$readJobs|Wait-Job|Receive-Job;if(@($reads|Where-Object {!$_.Ready}).Count){throw 'At least one client observed a non-ready server'};Write-Host "MULTI_USER_CONCURRENCY_OK references=$($numbers -join ', ') company=$($reads[0].Company)"}
finally{$jobs+$readJobs|Where-Object {$_}|Remove-Job -Force -ErrorAction SilentlyContinue}
